<script setup>
import {ref} from 'vue';
import {Head,Link,router} from '@inertiajs/vue3';
import {Search,Eye} from '@lucide/vue';
import AdminLayout from '../Components/AdminLayout.vue';
const props=defineProps({records:Object,filters:Object});
const search=ref(props.filters?.search || '');
function filter(){router.get('/admin/career',{search:search.value||undefined},{preserveState:true,replace:true});}
</script>
<template><Head title="Career applications"/><AdminLayout title="Career"><div class="page-heading"><div><span class="eyebrow">WEBSITE APPLICATIONS</span><h1>Career applications</h1><p>Review applicant details and download their supporting documents.</p></div></div><div class="panel"><form @submit.prevent="filter" class="career-search"><Search :size="18"/><input v-model="search" placeholder="Search name, email or phone"/><button class="btn" type="submit">Search</button></form><div class="career-table-wrap"><table><thead><tr><th>Applicant</th><th>Phone</th><th>Experience</th><th>Expected salary</th><th>Submitted</th><th></th></tr></thead><tbody><tr v-for="record in records.data" :key="record.id"><td><strong>{{record.name}}</strong><small>{{record.email}}</small></td><td>{{record.phone}}</td><td>{{record.years_of_experience}} years</td><td>৳{{Number(record.expected_salary).toLocaleString('en-BD')}}</td><td>{{new Date(record.created_at).toLocaleDateString()}}</td><td><Link :href="'/admin/career/'+record.id" class="btn"><Eye :size="16"/>View</Link></td></tr><tr v-if="!records.data.length"><td colspan="6" class="empty">No applications found.</td></tr></tbody></table></div><div class="career-pagination"><span>{{records.total}} applications</span><div><template v-for="link in records.links" :key="link.label"><Link v-if="link.url" :href="link.url" :class="['btn',{primary:link.active}]" v-html="link.label"/></template></div></div></div></AdminLayout></template>
<style scoped>.career-search{display:flex;align-items:center;gap:12px;padding:20px;border-bottom:1px solid #edf1ee;color:#809187}.career-search input{flex:1;min-width:0;border:0;background:transparent;outline:none;font-size:12px}.career-table-wrap{overflow:auto}table{width:100%;min-width:800px;border-collapse:collapse;font-size:12px}th{text-align:left;padding:16px 20px;background:#f7faf8;color:#819187;text-transform:uppercase;font-size:10px}td{padding:20px;border-top:1px solid #edf1ee}td strong{font-weight:600}td small{display:block;margin-top:6px;color:#87958d}.empty{text-align:center;color:#84938a}.career-pagination{display:flex;justify-content:space-between;align-items:center;padding:20px;font-size:11px;color:#809187}.career-pagination>div{display:flex;gap:5px}</style>
